import { normalizeText } from '../../core.js';
import { formatMoney } from '../../app/ui.js';
export function parseParticipants(value){return [...new Set((Array.isArray(value)?value:String(value||'').split(',')).map(x=>normalizeText(x,120)).filter(Boolean))]}
export function calculateSettlement(expenses=[]){const balance=new Map();for(const e of expenses){const participants=parseParticipants(e.participants);if(!e.payer||!Number.isFinite(e.amountVnd)||!participants.length)continue;const share=e.amountVnd/participants.length;for(const person of participants)balance.set(person,(balance.get(person)||0)-share);balance.set(e.payer,(balance.get(e.payer)||0)+e.amountVnd)}const creditors=[...balance].filter(([,v])=>v>0.5).map(([name,amount])=>({name,amount})).sort((a,b)=>b.amount-a.amount);const debtors=[...balance].filter(([,v])=>v<-0.5).map(([name,amount])=>({name,amount:-amount})).sort((a,b)=>b.amount-a.amount);const transfers=[];let i=0,j=0;while(i<debtors.length&&j<creditors.length){const amount=Math.min(debtors[i].amount,creditors[j].amount);if(amount>0.5)transfers.push({from:debtors[i].name,to:creditors[j].name,amount:Math.round(amount)});debtors[i].amount-=amount;creditors[j].amount-=amount;if(debtors[i].amount<0.5)i++;if(creditors[j].amount<0.5)j++;}return transfers}
export function renderSettlement(container, expenses=[]){const transfers=calculateSettlement(expenses);container.replaceChildren();if(!transfers.length){const p=document.createElement('p');p.className='meta settlement-empty';p.textContent=expenses.length?'Chưa đủ thông tin người chia hoặc mọi người đã cân bằng.':'Thêm khoản chi để tính ai nợ ai.';container.append(p);return}for(const t of transfers){const row=document.createElement('div');row.className='settlement-row';const text=document.createElement('span');text.textContent=`${t.from} → ${t.to}`;const money=document.createElement('strong');money.textContent=formatMoney(t.amount);row.append(text,money);container.append(row)}}
